			else { db_modify("update regnskab_partners set until = now(), note = concat(coalesce(note,''), ' | afsluttet af bogholder: ".db_escape_string($reason)."') where id = '".(int)$l['id']."'", __FILE__ . " linje " . __LINE__); db_modify("delete from partner_user_access where regnskab_id = '$arid' and bruger_id in (select bruger_id from partner_users where partner_id = '$pid')", __FILE__ . " linje " . __LINE__); db_modify("delete from partner_favorites where regnskab_id = '$arid' and bruger_id in (select bruger_id from partner_users where partner_id = '$pid')", __FILE__ . " linje " . __LINE__); bp_log(bp_is_group() ? 'partner.company_detached' : 'partner.link_removed', $arid, bp_partner()['name'].' – '.bp_t('afsluttet af','ended by').' '.bp_display_name().($reason ? ": $reason" : '')); vr_prg(array(bp_t('Firmaets adgang til','The firm\'s access to').' '.$reg['regnskab'].' '.bp_t('er afsluttet','has ended')), 'bogholder_panel.php'); }
		}
		else $notes[] = bp_t('Handlingen kræver en rettighed, du ikke har','The action requires a right you do not hold');
